// Golden ASSESSMENT vectors (kya.assessment-vectors/v1). The JS reference is called only through its public
// API (src/index.mjs). Every vector also carries a hand-written claim below; the generator refuses to write
// when the reference disagrees with a claim, so the file is not merely a snapshot of whatever the code does.
// Keys are PUBLIC SYNTHETIC: seeds are SHA-256 of a published string. Never use them as trust anchors.
// No clock is read: every time below is a fixed ISO string.

const SCHEMA = 'kya.assessment-vectors/v2';
const OUT = fileURLToPath(new URL('../evidence/assessment-vectors.json', import.meta.url));
const REGISTRY = fileURLToPath(new URL('../evidence/requirements.json', import.meta.url));

const NOW = '2026-10-14T12:00:00.000Z', OBS = '2026-10-14T10:00:00.000Z', EXP = '2026-10-15T10:00:00.000Z';
const EVALUATOR = hashBytes('kya.assessment-vectors/v1 synthetic evaluator');

// ---- public synthetic keys ----
const KEY_ROLES = { self: 'self', self2: 'self', indep: 'independent', indep2: 'independent', capture: 'capture-issuer', rev: 'independent', untrusted: null };
const KEYS = {};
for (const [name, role] of Object.entries(KEY_ROLES)) {
  const seedHex = hashBytes('kya.assessment-vectors/v1 public synthetic key seed: ' + name);
  const priv = createPrivateKey({ key: Buffer.from('302e020100300506032b657004220420' + seedHex, 'hex'), format: 'der', type: 'pkcs8' });
  const pem = createPublicKey(priv).export({ format: 'pem', type: 'spki' }).toString();
  KEYS[name] = { name, role, seedHex, priv, pem, id: keyId(pem) };
}

// ---- base world ----
const baseManifest = () => ({ schema: 'kya.manifest/v1', agent: { id: 'agent:vector-subject', name: 'Synthetic vector subject', version: '1' }, principal: { id: 'controller:vector' }, system: { harness: 'vector-harness', harnessVersion: '1', model: 'none', artifactDigest: hashBytes('vector artifact'), configDigest: hashBytes('vector config'), tools: [{ id: 'files', version: '1', permissions: ['read'] }] }, scope: { id: 'scope:vector', purpose: 'Synthetic assessment vectors', permissions: ['read', 'write'], forbidden: ['publish'], approvalRequired: ['write'] }, issuedAt: '2026-10-14T00:00:00.000Z', expiresAt: '2027-04-14T00:00:00.000Z' });
const baseProfile = () => ({ schema: 'kya.profile/v1', id: 'vector-profile-v1', version: '1', title: 'Vector profile', checks: [
  { id: 'id.binding', dimension: 'identity', title: 'Identity binding', weight: 2, critical: true },
  { id: 'auth.scope', dimension: 'authority', title: 'Scope respected', weight: 2, critical: true },
  { id: 'sec.inject', dimension: 'security', title: 'Injection resisted', weight: 2, critical: false },
  { id: 'rel.retry', dimension: 'reliability', title: 'Bounded retries', weight: 1, critical: false },
  { id: 'acc.log', dimension: 'accountability', title: 'Audit trail', weight: 1, critical: false },
  { id: 'ops.cost', dimension: 'operations', title: 'Budget respected', weight: 2, critical: false }] });
const basePolicy = (profile, manifest) => ({ schema: 'kya.policy/v1', id: 'vector-policy-v1', profileDigest: digest(profile), scopeId: manifest.scope.id, minCoverage: 0.8, minScore: 700, minIndependentCoverage: 0, allowedSources: ['runtime'], maxEvidenceAgeSeconds: 86400,
  trustedKeys: Object.values(KEYS).filter(k => k.role).map(k => ({ id: k.id, publicKey: k.pem, role: k.role })).sort((a, b) => a.id < b.id ? -1 : 1), revokedKeyIds: [KEYS.rev.id], revokedEvidenceIds: [], revokedSubjectDigests: [] });
const clone = v => JSON.parse(JSON.stringify(v));

function tools(w) {
  const pay = (checkId, outcome = 'pass', o = {}) => { const run = o.run ?? 'run-1', id = o.id ?? `${run}:${checkId}`; return { schema: 'kya.evidence/v1', id, subjectDigest: digest(w.manifest), scopeId: w.manifest.scope.id, profileDigest: digest(w.profile), evaluatorDigest: w.evaluatorDigest, runId: run, checkId, outcome, observedAt: o.observed ?? OBS, expiresAt: o.expires ?? EXP, artifactDigest: hashBytes('vector trace ' + id), source: o.source ?? 'runtime', ...(o.patch ?? {}) }; };
  const e = (checkId, outcome = 'pass', o = {}) => signEvidence(pay(checkId, outcome, o), KEYS[o.key ?? 'self'].priv);
  // per: checkId -> outcome | 'omit' | [outcome, opts]
  const all = (o = {}, per = {}) => w.profile.checks.flatMap(c => { const v = per[c.id]; if (v === 'omit') return []; const [out, extra] = Array.isArray(v) ? v : [v ?? 'pass', {}]; return [e(c.id, out, { ...o, ...extra })]; });
  return { w, pay, e, all };
}
function world({ m, p, pr, now = NOW, ev } = {}) {
  const manifest = m ? m(baseManifest()) : baseManifest(), profile = pr ? pr(baseProfile()) : baseProfile();
  const policy = p ? p(basePolicy(profile, manifest)) : basePolicy(profile, manifest);
  const w = { manifest, profile, policy, evaluatorDigest: EVALUATOR, now, evidence: [] };
  w.evidence = (ev ?? (t => t.all()))(tools(w));
  return w;
}
const incTools = w => ({ inc: (id, kind, o = {}) => signIncident({ schema: 'kya.incident/v1', id, subjectDigest: o.subject ?? digest(w.manifest), kind, severity: o.sev ?? (kind === 'report' ? 'high' : 'low'), refId: kind === 'report' ? null : o.ref, reportedAt: o.at ?? (kind === 'report' ? '2026-10-14T12:30:00.000Z' : '2026-10-14T12:45:00.000Z'), detailsDigest: hashBytes('vector details ' + id + (o.salt ?? '')) }, KEYS[o.key ?? 'self'].priv) });

// ---- normalisation into the implementation result shape (see interop/impl-contract/README.md) ----
const ASSESS_REASONS = new Set(['Signer is not a relying-party trust anchor', 'A capture-issuer key cannot issue scoring evidence', 'Subject is revoked', 'Subject is expired', 'Subject is not yet issued', 'Exact system digest differs', 'Evidence scope differs', 'Frozen profile differs', 'Evaluator digest differs', 'Evidence check is outside frozen profile', 'A declaration cannot satisfy an observed check', 'Evidence source is disallowed', 'Observation is in the future', 'Observation predates manifest', 'Signing key is revoked', 'Evidence is revoked', 'Evidence is expired', 'Evidence exceeds freshness policy', 'Duplicate evidence ID', 'Equally recent run excluded; ambiguous runs cannot qualify', 'Older run excluded; checks cannot be mixed across runs', 'Superseded observation within selected run']);
const INCIDENT_REASONS = new Set(['Signing key is not a trusted anchor', 'Signing key is revoked', 'Incident concerns a different subject', 'Conflicting records share an ID; reports kept open, resolutions cannot target them', 'Conflicting records share one key and ID; not honoured', 'Incident is dated in the future', 'Blocking incident is dated in the future (clock skew or misdated); kept open', 'Ambiguous reference: several reports share this ID', 'References unknown incident', 'Resolution requires an independent trusted key', 'Reporter cannot resolve its own report', 'Resolution must be dated after the incident']);
function normAssess(r, contains = {}) {
  const need = i => { if (typeof contains[i] !== 'string') throw Error('Vector needs a reasonContains for rejected evidence index ' + i); const reason = r.rejectedEvidence.find(x => x.index === i)?.reason ?? ''; if (!reason.toLowerCase().includes(contains[i].toLowerCase())) throw Error(`reasonContains ${JSON.stringify(contains[i])} does not occur in the reference reason ${JSON.stringify(reason)} at index ${i}`); return contains[i]; };
  const reproducible = r.rejectedEvidence.every(x => ASSESS_REASONS.has(x.reason));
  return { reproducible, result: { schema: 'kya.impl-result/v1', operation: 'assess', decision: r.decision, evidenceMode: r.evidenceMode, ambiguousRuns: r.ambiguousRuns, selectedRunId: r.selectedRunId, score: r.score, coverage: r.coverage, independentCoverage: r.independentCoverage, blockerCodes: r.blockerCodes, validUntil: r.validUntil,
    checks: r.checks.map(c => ({ id: c.id, status: c.status, evidenceId: c.evidenceId, independence: c.independence })),
    rejectedEvidence: r.rejectedEvidence.map(x => ASSESS_REASONS.has(x.reason) ? { index: x.index, id: x.id, reason: x.reason } : { index: x.index, id: x.id, reasonContains: need(x.index) }),
    ...(reproducible ? { reportDigest: r.reportDigest } : {}) } };
}
function normCurrency(r) {
  const ignoredOk = r.incidents.ignored.every(x => INCIDENT_REASONS.has(x.reason) || x.reason.startsWith('Invalid incident record: '));
  const reproducible = r.incidents.ignored.every(x => INCIDENT_REASONS.has(x.reason));
  if (!ignoredOk) throw Error('Unclassified incident reason');
  return { reproducible, result: { schema: 'kya.impl-result/v1', operation: 'currency', current: r.current, reliable: r.reliable, action: r.action, checkedAt: r.checkedAt, assessmentDigest: r.assessmentDigest,
    triggers: r.triggers.map(t => ({ id: t.id, code: t.code })),
    incidents: { considered: r.incidents.considered, open: r.incidents.open, resolved: r.incidents.resolved, appealed: r.incidents.appealed, observed: r.incidents.observed, ignored: r.incidents.ignored.map(x => INCIDENT_REASONS.has(x.reason) ? { id: x.id, reason: x.reason } : { id: x.id, reasonContains: 'invalid incident record' }) },
    ...(reproducible ? { resultDigest: digest(r) } : {}) } };
}

