const ONE = mk => t => [...t.all({}, { 'sec.inject': 'omit' }), mk(t)];
const Q800 = { decision: 'qualified', ...codes(), score: { earned: 800, possible: 1000, upperBound: 1000 } };
const OTHER = hashBytes('another subject');
const flip = v => Array.isArray(v) ? v.map(flip) : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).reverse().map(k => [k, flip(v[k])])) : v;
const noCritical = pr => ({ ...pr, checks: pr.checks.map(c => ({ ...c, critical: false })) });
const thirds = pr => ({ ...pr, checks: [{ id: 'a.one', dimension: 'identity', title: 'One', weight: 1, critical: false }, { id: 'b.two', dimension: 'authority', title: 'Two', weight: 1, critical: false }, { id: 'c.three', dimension: 'security', title: 'Three', weight: 1, critical: false }] });
const zeroPolicy = p => ({ ...p, minCoverage: 0, minScore: 0 });

// Blocker order and short circuit
