// ---- later additions to contract version 2: verify-credential, verify-score-card, compare-score-cards (ADR-0035) ----
const CRED = defineCredentialVectors({ O, OR, clone, REFUSE, world, assess, hashBytes, digest, keyId, PO0 });
defineScoreVectors({ O, OR, clone, REFUSE, hashBytes, digest });

// ---- build ----
function subset(claim, got, path = '') {
  if (claim === null || typeof claim !== 'object') { if (!Object.is(claim, got)) return `${path}: claimed ${JSON.stringify(claim)}, reference ${JSON.stringify(got)}`; return null; }
  if (Array.isArray(claim)) {
    if (!Array.isArray(got) || got.length !== claim.length) return `${path}: claimed length ${claim.length}, reference ${JSON.stringify(got)}`;
    for (let i = 0; i < claim.length; i++) { const d = subset(claim[i], got[i], `${path}[${i}]`); if (d) return d; }
    return null;
  }
  if (got === null || typeof got !== 'object') return `${path}: claimed object, reference ${JSON.stringify(got)}`;
  for (const k of Object.keys(claim)) { const d = subset(claim[k], got[k], `${path}.${k}`); if (d) return d; }
  return null;
}
const refuses = f => { try { f(); return null; } catch (e) { return e; } };

export function buildVectors(registry) {
  const known = new Set(registry.requirements.map(r => r.id)), seen = new Set(), vectors = [];
  for (const d of defs) {
    if (seen.has(d.id)) throw Error('Duplicate vector ID ' + d.id); seen.add(d.id);
    for (const r of d.requirements) if (!known.has(r)) throw Error(`Vector ${d.id} cites unknown requirement ${r}`);
    let inputs, expected, reproducible = true, got, rawInput;
    if (d.operation === 'assess') {
      const w = world(d.spec); inputs = { manifest: w.manifest, profile: w.profile, policy: w.policy, evidence: w.evidence, evaluatorDigest: w.evaluatorDigest, now: w.now };
      // post: edit the finished inputs (after signing). raw: edit the exact stdin text; such a vector carries rawInput and no inputs.
      if (d.spec.post) inputs = d.spec.post(clone(inputs), w);
      let run = inputs;
      if (d.spec.raw) {
        rawInput = d.spec.raw(JSON.stringify({ schema: 'kya.impl-input/v1', operation: 'assess', inputs }));
        const parsedRaw = refuses(() => parseJson(rawInput)) ? null : parseJson(rawInput);
        run = parsedRaw?.inputs ?? null;
        inputs = undefined;
      }
      const err = run === null ? Error('raw input is not strict JSON') : refuses(() => { got = assess(clone(run)); });
      if (err) expected = REFUSE; else { const n = normAssess(got, d.contains); expected = n.result; reproducible = n.reproducible; }
    } else {
      const w = world(d.spec.w ?? {}), assessment0 = assess(clone({ manifest: w.manifest, profile: w.profile, policy: w.policy, evidence: w.evidence, evaluatorDigest: w.evaluatorDigest, now: w.now }));
      const assessment = d.spec.a ? d.spec.a(clone(assessment0)) : assessment0;
      inputs = { assessment, manifest: d.spec.m ? d.spec.m(clone(w.manifest)) : w.manifest, policy: d.spec.p ? d.spec.p(clone(w.policy)) : w.policy, incidents: d.spec.inc ? d.spec.inc(incTools(w)) : [], now: d.spec.now ?? CNOW };
      const err = refuses(() => { got = checkCurrency(clone(inputs.assessment), { manifest: clone(inputs.manifest), policy: clone(inputs.policy), now: inputs.now, incidents: clone(inputs.incidents) }); });
      if (err) expected = REFUSE; else { const n = normCurrency(got); expected = n.result; reproducible = n.reproducible; }
    }
    const miss = subset(d.claim, expected);
    if (miss) throw Error(`Vector ${d.id}: reference disagrees with the written claim at ${miss}`);
    vectors.push({ id: d.id, description: d.description, requirements: [...d.requirements].sort(), rationale: d.rationale, operation: d.operation, ...(rawInput === undefined ? { inputs } : { rawInput }), expected, ...(reproducible ? {} : { digestReproducible: false }) });
  }
  // Contract version 2 operations. The expected value is the reference result; a claim (object or function) is written by hand and must hold.
  for (const d of OPS) {
    if (seen.has(d.id)) throw Error('Duplicate vector ID ' + d.id); seen.add(d.id);
    for (const r of d.requirements) if (!known.has(r)) throw Error(`Vector ${d.id} cites unknown requirement ${r}`);
    const inputs = clone(typeof d.inputs === 'function' ? d.inputs() : d.inputs);
    let got, rawInput;
    if (d.raw) {
      // The exact stdin text is edited after the envelope is written; the reference sees it through the strict parser like any adapter does.
      rawInput = d.raw(JSON.stringify({ schema: 'kya.impl-input/v1', operation: d.operation, inputs }));
      if (rawInput === JSON.stringify({ schema: 'kya.impl-input/v1', operation: d.operation, inputs })) throw Error(`Vector ${d.id}: the raw edit changed nothing`);
    }
    const run = d.raw ? (refuses(() => parseJson(rawInput)) ? null : parseJson(rawInput).inputs) : inputs;
    const err = run === null ? Error('raw input is not strict JSON') : refuses(() => { got = V2_OPERATIONS[d.operation](clone(run)); });
    const expected = err ? REFUSE : got;
    const miss = typeof d.claim === 'function' ? (err ? 'the reference refused' : d.claim(expected)) : subset(d.claim, expected);
    if (miss) throw Error(`Vector ${d.id}: reference disagrees with the written claim at ${miss}`);
    vectors.push({ id: d.id, description: d.description, requirements: [...d.requirements].sort(), rationale: d.rationale, operation: d.operation, ...(rawInput === undefined ? { inputs } : { rawInput }), expected });
  }
  const blockerCoverage = Object.fromEntries(BLOCKER_CODES.map(c => [c, vectors.filter(v => v.expected.blockerCodes?.includes(c)).map(v => v.id)]));
  const currencyCoverage = Object.fromEntries(Object.values(CURRENCY_CODES).map(c => [c, vectors.filter(v => v.expected.triggers?.some(t => t.code === c)).map(v => v.id)]));
  // NO_OBSERVED_CHECKS can only follow a would-be qualification with no scored check, and a qualification needs known weight above zero,
  // which means at least one selected check. The reference gate is defensive; no assess input can reach it.
  const unreachable = [{ code: 'NO_OBSERVED_CHECKS', reason: 'Qualification requires known weight above zero, which requires at least one selected check, so the reference gate is defensive and no input reaches it. A second implementation need not emit it.' }];
  for (const [c, ids] of Object.entries(blockerCoverage)) if (!ids.length && !unreachable.some(u => u.code === c)) throw Error('No vector exercises blocker code ' + c);
  for (const [c, ids] of Object.entries(currencyCoverage)) if (!ids.length) throw Error('No vector exercises currency code ' + c);
  const keys = Object.fromEntries(Object.values(KEYS).map(k => [k.name, { role: k.role ?? 'not-a-trust-anchor', seedDerivation: 'SHA-256 of the UTF-8 string "kya.assessment-vectors/v1 public synthetic key seed: ' + k.name + '"', seedHex: k.seedHex, keyId: k.id, publicKey: k.pem }]));
  return { schema: SCHEMA, contract: { version: 2, operations: ['assess', 'currency', 'canonicalize', 'digest', 'verify-envelope', 'compare', 'verify-credential', 'verify-score-card', 'compare-score-cards'] }, warning: 'PUBLIC SYNTHETIC keys, receipts and times for conformance testing only; never use these keys, seeds or trust anchors in a real assessment. Expected values were produced by the JavaScript reference and checked against hand-written claims in the generator; they are not independently derived.',
    runAtDefault: '2026-10-14T12:00:00.000Z', evaluatorDigestDerivation: 'SHA-256 of the UTF-8 string "kya.assessment-vectors/v1 synthetic evaluator"',
    comparison: 'Result must equal expected key for key. reasonContains is a lowercase keyword that must appear, case-insensitively, in the implementation reason. When digestReproducible is false the reportDigest or resultDigest is not compared, because the report includes implementation specific error text. {"refused":true} means the implementation must exit non-zero.',
    keys, credentialKeys: Object.fromEntries(Object.values(CRED.keys).map(k => [k.name, { seedDerivation: 'SHA-256 of the UTF-8 string "kya.assessment-vectors/v2 public synthetic credential key seed: ' + k.name + '"', seedHex: k.seedHex, did: k.did, publicKey: k.pem }])), unreachableBlockerCodes: unreachable, coverage: { blockerCodes: blockerCoverage, currencyCodes: currencyCoverage }, vectors };
}

async function generate() {
  const registry = JSON.parse(await readFile(REGISTRY, 'utf8'));
  const first = buildVectors(registry), second = buildVectors(registry);
  // Compared per part: the whole file is larger than the canonical JSON size bound (1 MiB), so canonical() cannot take it in one piece.
  const parts = f => [canonical({ ...f, vectors: [] }), ...f.vectors.map(v => canonical(v))];
  const [pa, pb] = [parts(first), parts(second)];
  if (pa.length !== pb.length || pa.some((x, i) => x !== pb[i])) throw Error('Generator is not deterministic: two runs differ; refusing to write');
  return JSON.stringify(first, null, 2) + '\n';
}

if (isMain(import.meta.url)) {
  const text = await generate();
  if (process.argv.includes('--print')) process.stdout.write(text);
  else if (process.argv.includes('--check')) {
    const current = await readFile(OUT, 'utf8').catch(() => '');
    if (current !== text) { console.error('Assessment vector drift; run node scripts/assessment-vectors.mjs'); process.exit(1); }
    console.log('Assessment vectors match');
  } else { await mkdir(fileURLToPath(new URL('../evidence/', import.meta.url)), { recursive: true }); await writeFile(OUT, text); console.log(`Assessment vectors written: ${JSON.parse(text).vectors.length} vectors`); }
}
export { generate };
